substring_with_concatenation_of_all_word.optimal:
word_len = length of a word, m = number of words, need = counts of words, result = empty list
for each offset in 0 .. word_len - 1:   (starts that share the same chunk grid)
    have = empty counts, left = offset, count = 0
    for each right from offset, stepping by word_len, while a chunk fits:
        chunk = s[right..right+word_len)
        if chunk not in need: have = empty, count = 0, left = right + word_len, continue   (a wall)
        have[chunk] += 1, count += 1
        while have[chunk] > need[chunk]: have[left chunk] -= 1, count -= 1, left += word_len
        if count == m:
            append left to result
            have[left chunk] -= 1, count -= 1, left += word_len
return result

minimum_window_substring.brute:
need = counts of t, best = ""
for each start in s:
    have = empty counts   (recounted for every start)
    for each end from start to the end of s:
        have[s[end]] += 1
        if have covers need (have[ch] >= need[ch] for every ch in need):
            if best is empty or end - start + 1 < length of best: best = s[start..end]
            stop extending this start
return best

minimum_window_substring.optimal:
need = counts of t, missing = length of t, left = 0, best_start = 0, best_len = +infinity
for each right in s, ch = s[right]:
    if need[ch] > 0: missing -= 1   (a copy we still needed)
    need[ch] -= 1   (below zero means surplus copies)
    if missing == 0:
        while need[s[left]] < 0: need[s[left]] += 1, left += 1   (drop surplus chars)
        if right - left + 1 < best_len: best_start = left, best_len = right - left + 1
        need[s[left]] += 1, missing += 1, left += 1   (evict one needed char; right must grow again)
if best_len is infinite: return ""
return s[best_start .. best_start + best_len)

subarrays_with_k_different_integers.optimal:
at_most(nums, limit):
    counts = dict value -> copies in the window, left = 0, total = 0
    for each right in nums, value = nums[right]:
        counts[value] += 1
        while counts has more than limit distinct keys:
            counts[nums[left]] -= 1, remove the key when it hits 0
            left += 1
        total += right - left + 1   (every start in [left, right] works)
    return total
return at_most(nums, k) - at_most(nums, k - 1)

sliding_window_maximum.brute:
out = empty list
for each start of a length-k window:
    biggest = nums[start]
    for each j in start + 1 .. start + k - 1: biggest = max(biggest, nums[j])   (rescans the window)
    append biggest to out
return out

sliding_window_maximum.optimal:
candidates = deque of indices (values strictly decreasing front to back), out = empty list
for each i in nums:
    while candidates is not empty and nums[back] <= nums[i]: pop the back   (never a maximum again)
    push i on the back
    if front <= i - k: pop the front   (it slid out of the window)
    if i >= k - 1: append nums[front] to out
return out

shortest_subarray_with_sum_at_least_k.optimal:
prefix = [0] followed by the running sums of nums, best = +infinity
starts = deque of indices whose prefix sums strictly increase
for each j in prefix:
    while starts is not empty and prefix[j] - prefix[front] >= k:
        best = min(best, j - front), pop the front   (a later j is only longer with this start)
    while starts is not empty and prefix[j] <= prefix[back]: pop the back   (dominated by j)
    push j on the back
return best, or -1 if never updated

longest_valid_parentheses.brute:
best = 0
for each start in s:
    balance = 0
    for each end from start to the end:   (re-matches pairs found from earlier starts)
        balance += 1 if s[end] == "(" else -1
        if balance < 0: stop extending this start   (a closer with no opener)
        if balance == 0: best = max(best, end - start + 1)
return best

longest_valid_parentheses.optimal:
stack = stack of indices holding -1   (the bottom is the barrier: last unmatched position)
best = 0
for each i in s:
    if s[i] == "(": push i
    else if the stack has more than one element:
        pop the top   (match the waiting "(")
        best = max(best, i - new top)   (the run reaches back to the new top)
    else: replace the bottom with i   (stray ")" becomes the new barrier)
return best

maximal_rectangle.brute:
full_of_ones(r1, c1, r2, c2): every cell between the two corners is "1"
if the matrix is empty: return 0
best = 0
for each top-left corner (r1, c1):
    for each bottom-right corner (r2, c2) with r2 >= r1 and c2 >= c1:   (rescans shared cells)
        if full_of_ones(r1, c1, r2, c2): best = max(best, (r2 - r1 + 1) * (c2 - c1 + 1))
return best

create_maximum_number.brute:
subsequences(nums, t): every subsequence of nums with exactly t digits, in order
interleavings(a, b): every merge of a and b that keeps the order inside each list
best = empty
for each i from max(0, k - size of nums2) to min(k, size of nums1):   (i digits from nums1)
    for each pick1 in subsequences(nums1, i):
        for each pick2 in subsequences(nums2, k - i):
            for each merged in interleavings(pick1, pick2):
                if merged > best: best = merged   (lists compare digit by digit)
return best
